use std::io::{self, Read};

// We need the Verus Prelude for `Seq`, `nat`, and the verifier attributes.
// In your workspace this may already be in scope; if not, uncomment:
// use verus::prelude::*;

/// A purely‐functional specification: count the number of times that
/// in the prefix of length `i` of sequence `s` we see the adjacent
/// pair `(a,b)`.  (So when `i < 2` the count is 0, else we recurse.)
#[verifier::spec]
fn count_transitions_prefix(s: Seq<char>, i: nat, a: char, b: char) -> nat {
    if i < 2 {
        0
    } else {
        let prev_count = count_transitions_prefix(s, i - 1, a, b);
        let new_pair = if s.index(i - 2) == a && s.index(i - 1) == b { 1 } else { 0 };
        prev_count + new_pair
    }
}

/// A convenience spec for the full string:
#[verifier::spec]
fn count_transitions(s: Seq<char>, a: char, b: char) -> nat {
    count_transitions_prefix(s, s.len(), a, b)
}

fn solve(n: usize, s: Vec<char>) -> Vec<char> {
    // Preconditions:
    //   1) the length of the Vec is exactly n,
    //   2) every character is either 'S' or 'F'.
    #[verifier::requires(s.len() == n)]
    #[verifier::requires(
        forall(|i: nat| i < n ==> (s.index(i) == 'S' || s.index(i) == 'F'))
    )]

    // Postcondition: we return exactly "YES" if
    //   count_transitions(s, 'S','F') > count_transitions(s, 'F','S')
    // else we return "NO".
    #[verifier::ensures(
        (count_transitions(view(s), 'S', 'F') > count_transitions(view(s), 'F', 'S')
            && result == vec!['Y','E','S'])
        ||
        (count_transitions(view(s), 'S', 'F') <= count_transitions(view(s), 'F', 'S')
            && result == vec!['N','O'])
    )]
    {
        let mut count_sf: usize = 0;
        let mut count_fs: usize = 0;
        let mut i: usize = 1;

        // We iterate i = 1..n, so we establish invariants at each step:
        #[verifier::invariant(1 <= i && i <= n)]
        #[verifier::invariant(count_sf as nat
            == count_transitions_prefix(view(&s), i, 'S', 'F'))]
        #[verifier::invariant(count_fs as nat
            == count_transitions_prefix(view(&s), i, 'F', 'S'))]
        #[verifier::decreases(n - i)]
        while i < n {
            match (s[i - 1], s[i]) {
                ('S', 'F') => {
                    count_sf += 1;
                    // after the increment, we establish the stronger invariant
                    assert(count_sf as nat
                        == count_transitions_prefix(view(&s), i + 1, 'S', 'F'));
                }
                ('F', 'S') => {
                    count_fs += 1;
                    assert(count_fs as nat
                        == count_transitions_prefix(view(&s), i + 1, 'F', 'S'));
                }
                _ => { }
            }
            i += 1;
        }

        if count_sf > count_fs {
            vec!['Y', 'E', 'S']
        } else {
            vec!['N', 'O']
        }
    }
}

fn main() {
    // Read the entire input
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    // Parse n and the sequence string
    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let s_str = parts.next().unwrap();

    // Convert the string into a Vec<char>
    let s_vec: Vec<char> = s_str.chars().collect();

    // Call solve and collect the result into a String
    let answer_chars = solve(n, s_vec);
    let answer: String = answer_chars.into_iter().collect();

    // Print the result
    println!("{}", answer);
}